public class RouterOutputFactory(string resourceName = null, Action<Humidifier.MediaConnect.RouterOutput> factoryAction = null) : ResourceFactory<Humidifier.MediaConnect.RouterOutput>(resourceName)
{

    internal InnerRouterOutputRouterOutputConfigurationFactory ConfigurationFactory { get; set; }

    internal InnerRouterOutputMaintenanceConfigurationFactory MaintenanceConfigurationFactory { get; set; }

    internal InnerRouterOutputFabricConfigurationFactory FabricConfigurationFactory { get; set; }

    protected override Humidifier.MediaConnect.RouterOutput Create()
    {
        var routerOutputResult = CreateRouterOutput();
        factoryAction?.Invoke(routerOutputResult);

        return routerOutputResult;
    }

    private Humidifier.MediaConnect.RouterOutput CreateRouterOutput()
    {
        var routerOutputResult = new Humidifier.MediaConnect.RouterOutput
        {
            GivenName = InputResourceName,
        };

        return routerOutputResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.RouterOutput result)
    {
        base.CreateChildren(result);

        result.Configuration ??= ConfigurationFactory?.Build();
        result.MaintenanceConfiguration ??= MaintenanceConfigurationFactory?.Build();
        result.FabricConfiguration ??= FabricConfigurationFactory?.Build();
    }

} // End Of Class

